pub const Properties = struct {
    grapheme: GraphemeClass,
    word: WordClass,
    sentence: SentenceClass,
    line: LineClass,
    bidi: BidiClass,
    script: Script,
    category: GeneralCategory,
    combining: u8,
    joining: JoiningType,
    east_asian_width: EastAsianWidth,
    indic_conjunct: IndicConjunctBreak,
    flags: u8,
    pub fn extendedPictographic(self: Properties) bool {
        return self.flags & 1 != 0;
    }
    pub fn defaultIgnorable(self: Properties) bool {
        return self.flags & 2 != 0;
    }
    pub fn alphabetic(self: Properties) bool {
        return self.flags & 4 != 0;
    }
    pub fn cased(self: Properties) bool {
        return self.flags & 8 != 0;
    }
    pub fn caseIgnorable(self: Properties) bool {
        return self.flags & 16 != 0;
    }
    pub fn graphemeExtend(self: Properties) bool {
        return self.flags & 32 != 0;
    }
    pub fn emojiPresentation(self: Properties) bool {
        return self.flags & 64 != 0;
    }
    pub fn whitespace(self: Properties) bool {
        return self.flags & 128 != 0;
    }
};

