    .{ .first = 0xffffe, .last = 0xfffff, .bits = 0x60004001d6000 },
    .{ .first = 0x100000, .last = 0x10fffd, .bits = 0x6004d6000 },
    .{ .first = 0x10fffe, .last = 0x10ffff, .bits = 0x60004001d6000 },
};

pub fn properties(scalar: u21) Properties {
    var low: usize = 0;
    var high: usize = ranges.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const range = ranges[middle];
        if (scalar < range.first) high = middle else if (scalar > range.last) low = middle + 1 else return unpack(range.bits);
    }
    return unpack(0);
}

fn unpack(value: u64) Properties {
    return .{
        .grapheme = @fromBackingInt(@intCast(value & 0xf)),
        .word = @fromBackingInt(@intCast((value >> 4) & 0x1f)),
        .sentence = @fromBackingInt(@intCast((value >> 9) & 0xf)),
        .line = @fromBackingInt(@intCast((value >> 13) & 0x3f)),
        .bidi = @fromBackingInt(@intCast((value >> 19) & 0x1f)),
        .script = @fromBackingInt(@intCast((value >> 24) & 0x1ff)),
        .category = @fromBackingInt(@intCast((value >> 33) & 0x1f)),
        .combining = @intCast((value >> 38) & 0xff),
        .joining = @fromBackingInt(@intCast((value >> 46) & 0x7)),
        .east_asian_width = @fromBackingInt(@intCast((value >> 49) & 0x7)),
        .indic_conjunct = @fromBackingInt(@intCast((value >> 52) & 0x3)),
        .flags = @intCast((value >> 54) & 0xff),
    };
}

