pub fn indicProperties(scalar: u21) IndicProperties {
    var low: usize = 0;
    var high: usize = indic_ranges.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const range = indic_ranges[middle];
        if (scalar < range.first) high = middle else if (scalar > range.last) low = middle + 1 else return .{ .syllabic = range.syllabic, .positional = range.positional };
    }
    return .{ .syllabic = .other, .positional = .not_applicable };
}

