    var low: usize = 0;
    var high: usize = decompositions.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const value = decompositions[middle];
        if (scalar < value.scalar) high = middle else if (scalar > value.scalar) low = middle + 1 else {
            if (value.compatibility and !compatibility) return null;
            return decomposition_scalars[value.offset..][0..value.length];
        }
    }
    return null;
}

