pub fn compose(first_scalar: u21, second_scalar: u21) ?u21 {
    var low: usize = 0;
    var high: usize = compositions.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const value = compositions[middle];
        if (first_scalar < value.first or (first_scalar == value.first and second_scalar < value.second)) high = middle else if (first_scalar > value.first or (first_scalar == value.first and second_scalar > value.second)) low = middle + 1 else return value.composed;
    }
    return null;
}

