pub fn caseMapping(scalar: u21) ?CaseMapping {
    var low: usize = 0;
    var high: usize = case_mappings.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const value = case_mappings[middle];
        if (scalar < value.scalar) high = middle else if (scalar > value.scalar) low = middle + 1 else return value;
    }
    return null;
}

