pub fn mirror(scalar: u21) ?u21 {
    var low: usize = 0;
    var high: usize = mirrors.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const value = mirrors[middle];
        if (scalar < value.scalar) high = middle else if (scalar > value.scalar) low = middle + 1 else return value.mirror;
    }
    return null;
}

